parameters.jsCode:
const ai = $json.output;

// =====================================================
// 1. BUDGET FIT SCORE (Max 4)
// Service-specific instead of one global budget score
// =====================================================

const budgetFit = {
  'API Integration': {
    'Under $100': 1,
    '$100 - $299': 3,
    '$300 - $599': 4,
    '$600 - $999': 4,
    '$1,000+': 4,
    'Not sure yet': 1,
  },

  'Lead / CRM Automation': {
    'Under $100': 0,
    '$100 - $299': 1,
    '$300 - $599': 3,
    '$600 - $999': 4,
    '$1,000+': 4,
    'Not sure yet': 1,
  },

  'Customer Support Automation': {
    'Under $100': 0,
    '$100 - $299': 1,
    '$300 - $599': 3,
    '$600 - $999': 4,
    '$1,000+': 4,
    'Not sure yet': 1,
  },

  'AI Automation': {
    'Under $100': 0,
    '$100 - $299': 1,
    '$300 - $599': 2,
    '$600 - $999': 3,
    '$1,000+': 4,
    'Not sure yet': 1,
  },

  'Business Process Automation': {
    'Under $100': 0,
    '$100 - $299': 1,
    '$300 - $599': 2,
    '$600 - $999': 3,
    '$1,000+': 4,
    'Not sure yet': 1,
  },

  'Document / RAG System': {
    'Under $100': 0,
    '$100 - $299': 0,
    '$300 - $599': 1,
    '$600 - $999': 3,
    '$1,000+': 4,
    'Not sure yet': 1,
  },

  'Other': {
    'Under $100': 0,
    '$100 - $299': 0,
    '$300 - $599': 0,
    '$600 - $999': 0,
    '$1,000+': 0,
    'Not sure yet': 0,
  },
};

const budgetScore =
  budgetFit[ai.service_category]?.[ai.budget] ?? 0;


// =====================================================
// 2. INTENT SCORE (Max 3)
// =====================================================

const intentScores = {
  ready_to_buy: 3,
  evaluating: 2,
  researching: 1,
  unclear: 0,
};

const intentScore = intentScores[ai.intent] ?? 0;


// =====================================================
// 3. TIMELINE SCORE (Max 2)
// ASAP is useful, but not automatically the best lead.
// =====================================================

const timelineScores = {
  'ASAP / Within 1 week': 1,
  '2 - 4 weeks': 2,
  '1 - 2 months': 2,
  'Flexible': 1,
  'Not sure yet': 0,
};

const timelineScore = timelineScores[ai.timeline] ?? 0;


// =====================================================
// 4. CLARITY SCORE (Max 1)
// =====================================================

const missingFields = Array.isArray(ai.missing_fields)
  ? ai.missing_fields
  : [];

const clarityScore = missingFields.length === 0 ? 1 : 0;


// =====================================================
// 5. TOTAL SCORE (Max 10)
// Budget 4 + Intent 3 + Timeline 2 + Clarity 1
// =====================================================

const leadScore =
  budgetScore +
  intentScore +
  timelineScore +
  clarityScore;


// =====================================================
// 6. FINAL STATUS
// Confidence is ONLY a review signal.
// It does not add business-quality points.
// =====================================================

let leadStatus;

if (
  ai.confidence < 0.60 ||
  ai.service_category === 'Other'
) {
  leadStatus = 'REVIEW';
}
else if (
  missingFields.length > 0 ||
  ai.intent === 'unclear'
) {
  leadStatus = 'NEEDS_INFO';
}
else if (leadScore >= 8) {
  leadStatus = 'HOT';
}
else if (leadScore >= 5) {
  leadStatus = 'WARM';
}
else {
  leadStatus = 'COLD';
}


// =====================================================
// 7. RETURN RESULT
// =====================================================

return {
  json: {
    ...$json,

    lead_score: leadScore,
    lead_status: leadStatus,

    score_breakdown: {
      budget_fit: budgetScore,
      intent: intentScore,
      timeline: timelineScore,
      clarity: clarityScore,
    },
  },
};

